mapper.select:
SELECT task_id,revision,created_at AS occurred_at FROM preparation_task_history
WHERE owner_id=#{owner} AND action='STATUS' AND JSON_UNQUOTE(JSON_EXTRACT(snapshot_json,'$.status'))='DONE'
  AND created_at>=#{from} AND created_at<#{until}

  AND (created_at<#{after.occurredAt}
    OR (created_at=#{after.occurredAt} AND task_id>#{after.taskId})
    OR (created_at=#{after.occurredAt} AND task_id=#{after.taskId} AND revision>#{after.revision}))

ORDER BY created_at DESC,task_id ASC,revision ASC LIMIT #{limit}
